// Generated by ipadport. Hosts the web app in a WKWebView and wires up the native bridge.

import SwiftUI
import WebKit

struct WebContainerView: UIViewRepresentable {
    var horizontalSizeClass: String
    var verticalSizeClass: String

    func makeCoordinator() -> NativeBridge {
        NativeBridge()
    }

    func makeUIView(context: Context) -> WKWebView {
        let configuration = WKWebViewConfiguration()
        configuration.setURLSchemeHandler(AppSchemeHandler(), forURLScheme: AppConfig.scheme)
        configuration.allowsInlineMediaPlayback = true
        configuration.mediaTypesRequiringUserActionForPlayback = []
        configuration.defaultWebpagePreferences.preferredContentMode = AppConfig.contentMode
        configuration.defaultWebpagePreferences.allowsContentJavaScript = true
        configuration.preferences.javaScriptCanOpenWindowsAutomatically = true
        if #available(iOS 16.4, *) {
            configuration.preferences.isElementFullscreenEnabled = true
        }

        let controller = configuration.userContentController
        let initial = "window.__IPADPORT_INITIAL__ = {horizontalSizeClass: '\(horizontalSizeClass)', verticalSizeClass: '\(verticalSizeClass)', idiom: '\(UIDevice.current.userInterfaceIdiom == .pad ? "pad" : "phone")'};"
        controller.addUserScript(WKUserScript(source: initial, injectionTime: .atDocumentStart, forMainFrameOnly: true))
        // Order matters: the shim defines window.ipadport, then the ported IPC handlers, then the app's preload.
        for name in ["ipadport-shim", "ipc-handlers", "preload"] {
            if let source = AppConfig.bundledText(name, ext: "js") {
                controller.addUserScript(WKUserScript(source: source, injectionTime: .atDocumentStart, forMainFrameOnly: true))
            }
        }
        controller.addScriptMessageHandler(context.coordinator, contentWorld: .page, name: "ipadport")

        let webView = WKWebView(frame: .zero, configuration: configuration)
        webView.navigationDelegate = context.coordinator
        webView.uiDelegate = context.coordinator
        webView.allowsBackForwardNavigationGestures = false
        webView.allowsLinkPreview = false
        webView.isOpaque = false
        webView.backgroundColor = .systemBackground
        webView.scrollView.contentInsetAdjustmentBehavior = AppConfig.edgeToEdge ? .never : .automatic
        webView.scrollView.keyboardDismissMode = .interactive
        if #available(iOS 16.4, *) {
            webView.isInspectable = AppConfig.inspectable
        }
        context.coordinator.webView = webView

        let refresh = UIRefreshControl()
        refresh.addTarget(context.coordinator, action: #selector(NativeBridge.reload(_:)), for: .valueChanged)
        if AppConfig.remoteURL != nil {
            webView.scrollView.refreshControl = refresh
        }

        webView.load(URLRequest(url: AppConfig.startURL))
        return webView
    }

    func updateUIView(_ webView: WKWebView, context: Context) {
        let script = "window.ipadport && window.ipadport._setSizeClass('\(horizontalSizeClass)', '\(verticalSizeClass)')"
        webView.evaluateJavaScript(script, completionHandler: nil)
    }
}
